{"results": [{"id": "hp_doc_4e83d655f618e92a46985de681b6aaff84f83373a5a4b8069b7bcc365e28954b", "title": "The Dutch Courtesan", "text": "The Dutch Courtesan is an early Jacobean stage play written by the dramatist and satirist John Marston circa 1604. It was performed by the Children of the Queen's Revels, one of the troupes of boy actors active at the time, in the Blackfriars Theatre in London.", "score": 39.3124}, {"id": "hp_doc_19892e00069f8d519fc67aa9c9a75cc793c73965b1cae928a2a76e9997c219c0", "title": "King's Revels Men", "text": "The King's Revels Men or King's Revels Company was a playing company or troupe of actors in seventeenth-century England. In the confusing theatre nomenclature of that era, it is sometimes called the \"second\" King's Revels Company, to distinguish it from an earlier troupe with the same title that was active in the 1607-9 period. Since the earlier group was a company of boy actors, they are alternatively referred to as the King's Revels Children, while the later troupe is termed the King's Revels Men.", "score": 20.2801}, {"id": "hp_doc_4beccbef2be3a99c5263a689901338fb5ab8ac662b249148bae380e6042c86bd", "title": "Parasitaster, or The Fawn", "text": "Parasitaster, or The Fawn is an early Jacobean play, written by the dramatist and satirist John Marston in 1604, and performed by the Children of the Queen's Revels in the Blackfriars Theatre.", "score": 19.6733}], "remaining_searches": 2}
